CREATE TABLE IF NOT EXISTS validation_check_category (
    id BINARY(16) NOT NULL PRIMARY KEY,
    name VARCHAR(150) NOT NULL,
    sort_order INT NOT NULL DEFAULT 0,
    is_active TINYINT(1) NOT NULL DEFAULT 1,
    note VARCHAR(500) NULL,
    created_by VARCHAR(100) NOT NULL,
    created_at DATETIME(6) NOT NULL,
    updated_by VARCHAR(100) NOT NULL,
    updated_at DATETIME(6) NOT NULL,
    row_version BIGINT NOT NULL DEFAULT 1,
    UNIQUE KEY ux_validation_check_category_name (name),
    KEY ix_validation_check_category_sort (is_active,sort_order,name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS validation_check_item (
    id BINARY(16) NOT NULL PRIMARY KEY,
    category_id BINARY(16) NOT NULL,
    content VARCHAR(1500) NOT NULL,
    default_information_source VARCHAR(30) NOT NULL DEFAULT '内部评审',
    sort_order INT NOT NULL DEFAULT 0,
    is_active TINYINT(1) NOT NULL DEFAULT 1,
    note VARCHAR(500) NULL,
    created_by VARCHAR(100) NOT NULL,
    created_at DATETIME(6) NOT NULL,
    updated_by VARCHAR(100) NOT NULL,
    updated_at DATETIME(6) NOT NULL,
    row_version BIGINT NOT NULL DEFAULT 1,
    CONSTRAINT fk_validation_check_item_category FOREIGN KEY (category_id) REFERENCES validation_check_category(id),
    KEY ix_validation_check_item_category_sort (category_id,is_active,sort_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS project_validation_plan (
    id BINARY(16) NOT NULL PRIMARY KEY,
    project_id BINARY(16) NOT NULL,
    prepared_by VARCHAR(100) NULL,
    validation_date DATE NULL,
    created_by VARCHAR(100) NOT NULL,
    created_at DATETIME(6) NOT NULL,
    updated_by VARCHAR(100) NOT NULL,
    updated_at DATETIME(6) NOT NULL,
    row_version BIGINT NOT NULL DEFAULT 1,
    CONSTRAINT fk_project_validation_plan_project FOREIGN KEY (project_id) REFERENCES project(id),
    UNIQUE KEY ux_project_validation_plan_project (project_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS project_validation_plan_item (
    id BINARY(16) NOT NULL PRIMARY KEY,
    plan_id BINARY(16) NOT NULL,
    catalog_category_id BINARY(16) NOT NULL,
    catalog_item_id BINARY(16) NOT NULL,
    category_name VARCHAR(150) NOT NULL,
    validation_content VARCHAR(1500) NOT NULL,
    information_source VARCHAR(30) NULL,
    validation_date DATE NULL,
    result VARCHAR(1500) NULL,
    responsible_person VARCHAR(100) NULL,
    remark VARCHAR(1000) NULL,
    sort_order INT NOT NULL DEFAULT 0,
    CONSTRAINT fk_project_validation_plan_item_plan FOREIGN KEY (plan_id) REFERENCES project_validation_plan(id) ON DELETE CASCADE,
    CONSTRAINT fk_project_validation_plan_item_category FOREIGN KEY (catalog_category_id) REFERENCES validation_check_category(id),
    CONSTRAINT fk_project_validation_plan_item_catalog FOREIGN KEY (catalog_item_id) REFERENCES validation_check_item(id),
    UNIQUE KEY ux_project_validation_plan_item_catalog (plan_id,catalog_item_id),
    KEY ix_project_validation_plan_item_sort (plan_id,sort_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

SELECT role_code,'validation-plan.edit',UTC_TIMESTAMP(6)
FROM role_definition
WHERE role_code IN ('Engineer','ElectricalEngineer','CommissioningEngineer','HardwareEngineer','MechanicalManager','TechnicalAssistant','ProjectManager','BusinessUnitManager','Administrator','developer')
ON DUPLICATE KEY UPDATE updated_at=VALUES(updated_at);

SELECT role_code,'validation-catalog.manage',UTC_TIMESTAMP(6)
FROM role_definition
WHERE role_code IN ('ProcessReviewer','Approver','Administrator','developer')
ON DUPLICATE KEY UPDATE updated_at=VALUES(updated_at);

